-- HOCKER AGI canonical registry 12.6C.1B (part 1/4)
create extension if not exists pgcrypto;

create or replace function public.canonical_agi_id(p_agi_id text)
returns text
language sql
immutable
set search_path = public
as $$
  select case lower(regexp_replace(coalesce(trim(p_agi_id), ''), '[\s-]+', '_', 'g'))
    when 'candy_ads' then 'candy'
    when 'chido_gerente' then 'chido_gerente'
    when 'chido_wins' then 'chido_wins'
    when 'nexpa_agi' then 'nexpa'
    when 'nova_ads' then 'nova_ads'
    when 'pro_ia' then 'pro_ia'
    when 'pro' then 'pro_ia'
    when 'trackhok_agi' then 'trackhok'
    when 'shadows_ia' then 'shadows'
    else lower(regexp_replace(coalesce(trim(p_agi_id), ''), '[\s-]+', '_', 'g'))
  end;
$$;

create or replace function public.normalize_agi_id_before_write()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  new.agi_id := public.canonical_agi_id(new.agi_id);
  return new;
end;
$$;

